import mpmath, random
random.seed(1)
vals = [9.995074823339339e-05, 0.999, 0.9999, 9.999, 9.9999, 0.0999, 0.00999, 0.000999, 1.0, 999.999, 0.1, 0.15, 0.25, 2.5, 9.5]
for _ in range(2000):
    vals.append(random.uniform(-1e6,1e6))
    vals.append(random.uniform(-1e-6,1e-6))
specs = ['.0g','.1g','.2g','.3g','.4g','.5g','.6g','.0f','.1f','.2f','.3f','.0e','.1e','.2e','g','f','e','E','%.2f']
fails=0
for v in vals:
    for sp in specs:
        try:
            a=format(mpmath.mpf(v), sp)
        except Exception as e:
            a='ERR:'+str(e)
        try:
            b=format(v, sp)
        except Exception as e:
            b='ERR:'+str(e)
        if a!=b:
            fails+=1
            if fails<30: print(repr(v), sp, 'mpmath=',a,'c=',b)
print('total fails', fails)
""}

